extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var basket := await instantiate_main_scene()
	if not check("basket_ok", basket != null, "La scena basket.tscn deve istanziarsi correttamente"):
		return
	check("has_check_rubies", has_function(basket, "check_rubies"), "basket.gd deve avere la funzione check_rubies")
	var initial_rubies: Array = get_prop(basket, "rubies", [])
	var initial_count: int = initial_rubies.size()
	var ruby = call_if_exists(basket, "spawn_ruby", [Vector2(0, 700.0)]) as Sprite2D
	if not check("ruby_spawn", ruby != null, "spawn_ruby deve restituire il rubino generato"):
		return
	await wait_frames(2)
	check("ruby_freed", not is_instance_valid(ruby), "Il rubino oltre la soglia deve essere eliminato con queue_free()")
	var rubies_arr: Array = get_prop(basket, "rubies", [])
	check("ruby_removed", rubies_arr.size() == initial_count, "Il rubino eliminato deve essere rimosso dall'array rubies")
	call_if_exists(basket, "reset_game")
	await wait_frames(2)
	var stars_after: Array = get_prop(basket, "stars", [])
	var rubies_after: Array = get_prop(basket, "rubies", [])
	check("reset_stars_clean", stars_after.size() == 0, "reset_game deve svuotare l'array stars")
	check("reset_rubies_clean", rubies_after.size() == 0, "reset_game deve svuotare l'array rubies")
